--
-- Name: v_daily_aggregation; Type: VIEW; Schema: public; Owner: warehouse_user
--

CREATE VIEW public.v_daily_aggregation AS
 SELECT ih.warehouse_id,
    w.code AS warehouse_code,
    date(ih.scanned_at) AS scan_date,
    count(*) AS total_scans,
    sum(ih.quantity) AS total_quantity,
    sum(ih.difference) AS total_difference,
    sum(abs(ih.difference)) AS total_abs_difference,
    count(DISTINCT ih.product_id) AS unique_products_scanned,
    count(DISTINCT ih.robot_id) AS unique_robots
   FROM (((public.inventory_history ih
     JOIN public.warehouses w ON (((w.id = ih.warehouse_id) AND (w.is_deleted = false))))
     JOIN public.products p ON (((p.id = ih.product_id) AND (p.is_deleted = false))))
     JOIN public.product_warehouse pw ON (((pw.product_id = ih.product_id) AND (pw.warehouse_id = ih.warehouse_id) AND (pw.is_deleted = false))))
  WHERE (ih.is_deleted = false)
  GROUP BY ih.warehouse_id, w.code, (date(ih.scanned_at));


ALTER VIEW public.v_daily_aggregation OWNER TO warehouse_user;

--
-- Name: v_discrepancy_summary; Type: VIEW; Schema: public; Owner: warehouse_user
--

CREATE VIEW public.v_discrepancy_summary AS
 SELECT w.code AS warehouse_code,
    w.name AS warehouse_name,
    p.sku_code,
    p.name AS product_name,
    count(*) AS scan_count,
    sum(abs(ih.difference)) AS total_abs_discrepancy,
    avg(abs(ih.difference)) AS avg_discrepancy,
    max(abs(ih.difference)) AS max_discrepancy,
    max(ih.scanned_at) AS last_discrepancy_at
   FROM ((public.inventory_history ih
     JOIN public.warehouses w ON (((w.id = ih.warehouse_id) AND (w.is_deleted = false))))
     JOIN public.products p ON (((p.id = ih.product_id) AND (p.is_deleted = false))))
  WHERE ((ih.is_deleted = false) AND (ih.difference <> 0) AND (ih.scanned_at >= (now() - '30 days'::interval)))
  GROUP BY w.code, w.name, p.sku_code, p.name;


ALTER VIEW public.v_discrepancy_summary OWNER TO warehouse_user;

--
-- Name: v_product_report; Type: VIEW; Schema: public; Owner: warehouse_user
--

CREATE VIEW public.v_product_report AS
 SELECT p.id AS product_id,
    p.sku_code,
    p.name AS product_name,
    p.category,
    w.code AS warehouse_code,
    w.name AS warehouse_name,
    pw.min_stock,
    pw.optimal_stock,
    ih.quantity AS current_quantity,
    ih.expected_quantity,
    ih.difference,
        CASE
            WHEN (ih.quantity <= pw.min_stock) THEN 'CRITICAL'::text
            WHEN (ih.quantity <= pw.optimal_stock) THEN 'LOW_STOCK'::text
            ELSE 'OK'::text
        END AS inventory_status,
    ih.scanned_at AS last_scanned_at
   FROM (((public.products p
     CROSS JOIN public.warehouses w)
     JOIN public.product_warehouse pw ON (((pw.product_id = p.id) AND (pw.warehouse_id = w.id) AND (pw.is_deleted = false))))
     LEFT JOIN LATERAL ( SELECT ih2.quantity,
            ih2.expected_quantity,
            ih2.difference,
            ih2.scanned_at
           FROM public.inventory_history ih2
          WHERE ((ih2.product_id = p.id) AND (ih2.warehouse_id = w.id) AND (ih2.is_deleted = false))
          ORDER BY ih2.scanned_at DESC
         LIMIT 1) ih ON (true))
  WHERE ((p.is_deleted = false) AND (w.is_deleted = false));


ALTER VIEW public.v_product_report OWNER TO warehouse_user;

--
-- Name: v_robot_activity_report; Type: VIEW; Schema: public; Owner: warehouse_user
--

CREATE VIEW public.v_robot_activity_report AS
 SELECT r.id AS robot_id,
    r.robot_code,
    w.code AS warehouse_code,
    w.name AS warehouse_name,
    rs.code AS robot_status,
    r.battery_level,
    r.last_update,
    COALESCE(sc.scan_count, (0)::bigint) AS total_scans,
    COALESCE(sc.last_scan_at, NULL::timestamp without time zone) AS last_scan_at,
    COALESCE(sc.ok_count, (0)::bigint) AS ok_scans,
    COALESCE(sc.low_stock_count, (0)::bigint) AS low_stock_scans,
    COALESCE(sc.critical_count, (0)::bigint) AS critical_scans,
    COALESCE(sc.total_diff, (0)::bigint) AS total_difference
   FROM (((public.robots r
     JOIN public.warehouses w ON (((w.id = r.warehouse_id) AND (w.is_deleted = false))))
     JOIN public.robot_status rs ON ((rs.id = r.status_id)))
     LEFT JOIN LATERAL ( SELECT count(*) AS scan_count,
            max(ih.scanned_at) AS last_scan_at,
            count(*) FILTER (WHERE ((ist.code)::text = 'OK'::text)) AS ok_count,
            count(*) FILTER (WHERE ((ist.code)::text = 'LOW_STOCK'::text)) AS low_stock_count,
            count(*) FILTER (WHERE ((ist.code)::text = 'CRITICAL'::text)) AS critical_count,
            COALESCE(sum(ih.difference), (0)::bigint) AS total_diff
           FROM (public.inventory_history ih
             JOIN public.inventory_status ist ON ((ist.id = ih.status_id)))
          WHERE ((ih.robot_id = r.id) AND (ih.is_deleted = false))) sc ON (true))
  WHERE (r.is_deleted = false);


ALTER VIEW public.v_robot_activity_report OWNER TO warehouse_user;

--
-- Name: v_warehouse_summary; Type: VIEW; Schema: public; Owner: warehouse_user
--

CREATE VIEW public.v_warehouse_summary AS
 SELECT w.id AS warehouse_id,
    w.code AS warehouse_code,
    w.name AS warehouse_name,
    COALESCE(sum(ih.quantity), (0)::bigint) AS total_quantity,
    COALESCE(count(DISTINCT ih.product_id), (0)::bigint) AS unique_sku_count,
    COALESCE(sum(ih.difference), (0)::bigint) AS total_discrepancy,
    COALESCE(sum(abs(ih.difference)), (0)::bigint) AS total_abs_discrepancy,
    max(ih.scanned_at) AS last_scan_at,
    COALESCE(sum(ih.quantity) FILTER (WHERE (ih.status_id = ( SELECT inventory_status.id
           FROM public.inventory_status
          WHERE ((inventory_status.code)::text = 'CRITICAL'::text)))), (0)::bigint) AS critical_count,
    COALESCE(sum(ih.quantity) FILTER (WHERE (ih.status_id = ( SELECT inventory_status.id
           FROM public.inventory_status
          WHERE ((inventory_status.code)::text = 'LOW_STOCK'::text)))), (0)::bigint) AS low_stock_count
   FROM (public.warehouses w
     LEFT JOIN LATERAL ( SELECT DISTINCT ON (ih2.product_id) ih2.product_id,
            ih2.quantity,
            ih2.difference,
            ih2.scanned_at,
            ih2.status_id
           FROM ((public.inventory_history ih2
             JOIN public.products p2 ON (((p2.id = ih2.product_id) AND (p2.is_deleted = false))))
             JOIN public.product_warehouse pw2 ON (((pw2.product_id = ih2.product_id) AND (pw2.warehouse_id = ih2.warehouse_id) AND (pw2.is_deleted = false))))
          WHERE ((ih2.warehouse_id = w.id) AND (ih2.is_deleted = false))
          ORDER BY ih2.product_id, ih2.scanned_at DESC) ih ON (true))
  WHERE (w.is_deleted = false)
  GROUP BY w.id, w.code, w.name;


ALTER VIEW public.v_warehouse_summary OWNER TO warehouse_user;

